return {["PeachBlossomSong"]={["1"]={["action"]=[[$N使出一招直奔$n要害，见势$n将手中$W迎了上去以巧劲将其化解。]],["id"]=1,["textColor"]=[[默认]]},["2"]={["action"]=[[“叮当”两声脆响，$N的攻击被$n用手中$W巧妙化解。]],["id"]=2,["textColor"]=[[默认]]},["3"]={["action"]=[[见势$n后撤一步，以手中$W弹开$N击来招式将其化解。]],["id"]=3,["textColor"]=[[默认]]}},["TiangangZhuaIII"]={["1"]={["action"]=[[眼见$N袭向$n，但$n却不躲不闪，双手似灵蛇般勾缠住$N腕部，一翻一转便破了攻击。]],["id"]=1,["textColor"]=[[默认]]},["2"]={["action"]=[=[$n身子微微一侧，使出一式[流光瞬息]，在$N的攻来的瞬间躲开了$N的攻势。]=],["id"]=2,["textColor"]=[[默认]]},["3"]={["action"]=[[$n身形急退，一招「天车凌云」，快速的避开了攻击。]],["id"]=3,["textColor"]=[[默认]]}},["bingweimoquan"]={["1"]={["action"]=[[$n身子微微一侧，已躲开$N的攻势。]],["id"]=1,["textColor"]=[[YEL]]},["2"]={["action"]=[[$n一招RAN「围魏救赵」NOR，不退反进，击向$N，逼得$N回招自保。]],["id"]=2,["textColor"]=[[YEL]]},["3"]={["action"]=[[$n双拳错落，护住全身要害。]],["id"]=3,["textColor"]=[[YEL]]},["4"]={["action"]=[[$N眼前一花，所有的招式好象击在了虚处，仔细一看，$n站在原地没有动过。]],["id"]=4,["textColor"]=[[YEL]]}},["brightLunaDuskyCandle"]={["1"]={["action"]=[[$n见$N攻势凶猛，使出一式「鸣熄」，当即头侧偏一方似留有残影将袭来招式躲过。]],["id"]=1,["textColor"]=[[默认]]},["2"]={["action"]=[[$N见势击出一击，$n当即使出一式「寒凉」，下一瞬身似鬼魅幻影将招式化解。]],["id"]=2,["textColor"]=[[默认]]},["3"]={["action"]=[[$n见势不妙，当即使出一式「寒霜」，招出双脚变换之快似有流影，$N招数落空显露破绽。]],["id"]=3,["textColor"]=[[默认]]}},["chan"]={["1"]={["action"]=[[$n护住要害，并一把将对方推开。]],["anim"]=[[snake-defend]],["hitPos"]=[[chest]],["id"]=1,["offset"]=-200,["textColor"]=[[默认]]},["2"]={["action"]=[[$n护住要害，并一把将对方推开。]],["anim"]=[[snake-defend]],["hitPos"]=[[foot]],["id"]=2,["offset"]=-200,["textColor"]=[[默认]]},["3"]={["action"]=[[$n护住要害，并一把将对方推开。]],["anim"]=[[snake-defend]],["hitPos"]=[[head]],["id"]=3,["offset"]=-200,["textColor"]=[[默认]]}},["dazangzhangxueyinshou"]={["1"]={["action"]=[[$n双掌微合，使出一招RAN「千里迎刹佛」NOR，RAN「啪」NOR的一声将$N的$w夹在双掌之间。]],["id"]=1,["textColor"]=[[CYN]]},["2"]={["action"]=[[$n略一转身，一招RAN「撒手离红尘」NOR拍向$N拿着$w的手。]],["id"]=2,["textColor"]=[[CYN]]},["3"]={["action"]=[[$n使出RAN「粘」NOR字诀，双掌一划，引偏了$N的$w。]],["id"]=3,["textColor"]=[[CYN]]},["4"]={["action"]=[[$n施展出RAN「万象皆归空」NOR，轻描淡写的化解了$N的攻势。]],["id"]=4,["textColor"]=[[CYN]]}},["dugujiujian"]={["1"]={["action"]=[[却见$n踏前一步，剑式斜指你的右臂，想要使$P闪身而退。]],["id"]=1,["textColor"]=[[默认]]},["2"]={["action"]=[[$n以攻为守，以进为退，凝神运气向$P猛攻快打地挥出方位大异的泰山「快活三」三剑。]],["id"]=2,["textColor"]=[[默认]]},["3"]={["action"]=[[$n剑法突变，剑势伸缩不定，奔腾矫夭，逆使朝日出岫剑的「天外玉龙」企图迫使$P变招。]],["id"]=3,["textColor"]=[[默认]]},["4"]={["action"]=[[$n突然一剑点向$P的$l，虽一剑却暗藏无数后着，$P手足无措，攻势不由自主停了下来。]],["id"]=4,["textColor"]=[[默认]]},["5"]={["action"]=[[$n不闪不避，举剑闪电般使出「叠翠浮青」反削$P的$l，想挡过你此招。]],["id"]=5,["textColor"]=[[默认]]},["6"]={["action"]=[[$n突然使出青城派风饕剑法的「鸿飞冥冥」，长剑对着$P一绞，企图突破$P的攻势。]],["id"]=6,["textColor"]=[[默认]]},["7"]={["action"]=[[$n挺剑一招象是「白云出岫」回刺$P的$l，企图将$P的攻势化解。]],["id"]=7,["textColor"]=[[默认]]},["8"]={["action"]=[[只见$n不退反进，身如飘风，一式「天柱云气」动向无定，挡住了$P的进攻。]],["id"]=8,["textColor"]=[[默认]]},["9"]={["action"]=[[$n不退反进，使出恒山剑招「绵里藏针」，森森剑气充溢四周！架开了$P的这招。]],["id"]=9,["textColor"]=[[默认]]}},["feixianjianfa"]={["1"]={["action"]=[[$n使出一招「凤舞九天」，手中的$w化作一条长虹，磕开了$N]],["id"]=1,["textColor"]=[[YEL]]},["2"]={["action"]=[[$n使出「封」字诀，将$N封于丈外。]],["id"]=2,["textColor"]=[[YEL]]},["3"]={["action"]=[[$n使出一招「朝朝瑞雪」，手中的$w化做漫天雪影，荡开了$N]],["id"]=3,["textColor"]=[[YEL]]},["4"]={["action"]=[[$n手中的$w一抖，一招「旱地春雷」，向$N的手腕削去。]],["id"]=4,["textColor"]=[[YEL]]}},["gouyao"]={["1"]={["action"]=[[但是$n身子一侧，轻松地格开。]],["anim"]=[[wolf-defend]],["hitPos"]=[[chest]],["id"]=1,["offset"]=-200,["textColor"]=[[YEL]]},["2"]={["action"]=[[但是$n身子一侧，轻松地格开。]],["anim"]=[[wolf-defend]],["hitPos"]=[[foot]],["id"]=2,["offset"]=-200,["textColor"]=[[YEL]]},["3"]={["action"]=[[但是$n身子一侧，轻松地格开。]],["anim"]=[[wolf-defend]],["hitPos"]=[[head]],["id"]=3,["offset"]=-200,["textColor"]=[[YEL]]}},["greenWindHuan"]={["1"]={["action"]=[[$n见$N使出一招，当即将手中$W护在面前，只听“铮”一声，$W将$N击来招式化解。]],["anim"]=[[qlhj_defend_chest]],["hitPos"]=[[chest]],["id"]=1,["offset"]=-200,["textColor"]=[[YEL]]},["2"]={["action"]=[[$N见机击出一招，$n当即将手中$W护在身前，“当”一声脆响，$n挡住了$N的招数。]],["anim"]=[[qlhj_defend_foot]],["hitPos"]=[[foot]],["id"]=2,["offset"]=-200,["textColor"]=[[YEL]]},["3"]={["action"]=[[“锵”一声脆响，$n手中$W传来震感，抵挡住了$N的招式。]],["anim"]=[[qlhj_defend_head]],["hitPos"]=[[head]],["id"]=3,["offset"]=-200,["textColor"]=[[YEL]]},["4"]={["action"]=[[$n当即将手中$W护在面前，只听“铮”一声化解击来的招式。]],["id"]=4,["textColor"]=[[YEL]]}},["guisha"]={["1"]={["action"]=[[但是$n身体虚不受力，挡住了这一击、。]],["id"]=1,["textColor"]=[[RAN]]},["2"]={["action"]=[[但是$n身体虚不受力，挡住了这一击、。]],["id"]=2,["textColor"]=[[RAN]]},["3"]={["action"]=[[但是$n身体虚不受力，挡住了这一击、。]],["id"]=3,["textColor"]=[[RAN]]}},["jibenzhaojia"]={["1"]={["action"]=[[只听见「锵」一声，被$p格开了。]],["id"]=1,["textColor"]=[[YEL]]},["2"]={["action"]=[[结果「当」地一声被$p挡开了。]],["id"]=2,["textColor"]=[[YEL]]},["3"]={["action"]=[[但是被$n架开。]],["id"]=3,["textColor"]=[[YEL]]},["4"]={["action"]=[[但是$n身子一侧，轻松地格开。]],["id"]=4,["textColor"]=[[YEL]]}},["luaoyuanmingliuquanshu"]={["1"]={["action"]=[[$n一把刁住$N的手腕，用力向后一捌，将$N用力甩了出去，「狼牙」！！]],["id"]=1,["textColor"]=[[YEL]]},["2"]={["action"]=[[$n乘$N攻击时闪出的一处破绽，突然使出一招「浮狱」，一头撞向$N的额部。]],["id"]=2,["textColor"]=[[YEL]]},["3"]={["action"]=[[$N眼看就要攻击到$n的一瞬间，$n一招「浮身」向后一跃，闪过了这一招。]],["id"]=3,["textColor"]=[[YEL]]},["4"]={["action"]=[[$n趁着$N攻击的间隙，突然欺近。一拳击向$N的面门，用「蔓落」化解了这一招。]],["id"]=4,["textColor"]=[[YEL]]},["5"]={["action"]=[[$n突然伸指截向$N的双眼，$N慌乱之际只能停止进攻，正是一招「指穿」。]],["id"]=5,["textColor"]=[[YEL]]},["6"]={["action"]=[[$n一口唾液吐向$N的眼睛，一招「讣霞」躲过了$N的攻击。]],["id"]=6,["textColor"]=[[YEL]]}},["niaozhuo"]={["1"]={["action"]=[[但是$n身子一侧，轻松地格开。]],["anim"]=[[bird-defend]],["hitPos"]=[[chest]],["id"]=1,["offset"]=-200,["textColor"]=[[YEL]]},["2"]={["action"]=[[但是$n身子一侧，轻松地格开。]],["anim"]=[[bird-defend]],["hitPos"]=[[foot]],["id"]=2,["offset"]=-200,["textColor"]=[[YEL]]},["3"]={["action"]=[[但是$n身子一侧，轻松地格开。]],["anim"]=[[bird-defend]],["hitPos"]=[[head]],["id"]=3,["offset"]=-200,["textColor"]=[[YEL]]}},["qiugeqidao"]={["1"]={["action"]=[[$n使出一招「风摇山竹寒声动」，手中的$W散出丝丝寒气格开了$P]],["id"]=1,["textColor"]=[[YEL]]},["2"]={["action"]=[[$n手中$W虚晃数刀，一招「淡烟疏雨间斜阳」，刀影中突然爆出一缕光芒从侧面划向$P之必救。]],["id"]=2,["textColor"]=[[YEL]]},["3"]={["action"]=[[$n身形微顿，手中的$W化作一道弧光，一招「雁点青天字一行」，反削$P]],["id"]=3,["textColor"]=[[YEL]]},["4"]={["action"]=[[$n使出一招「霜凋红叶正晚秋」，手中的$W内力激荡，$N的攻势随波而散。]],["id"]=4,["textColor"]=[[YEL]]},["5"]={["action"]=[[$n身形急退，手中$W上下飞舞，一招「雨过天连青壁润」，封住$N的招式。]],["id"]=5,["textColor"]=[[YEL]]},["6"]={["action"]=[[$n手中的$W挽出朵朵刀花，一招「金花玉萼影浮沉」，游刃有余。]],["id"]=6,["textColor"]=[[YEL]]}},["riyuelun"]={["1"]={["action"]=[[$n不躲不避，手中$w摆开，在$P跟前形成了一道光幕，$N此招根本无法再进。]],["id"]=1,["textColor"]=[[YEL]]},["2"]={["action"]=[[却见$n踏前一步，手中$w翻飞，其势甚巨，$N前进不能，只好闪身而退。]],["id"]=2,["textColor"]=[[YEL]]},["3"]={["action"]=[[$n轮法突变，$w带着风声飞舞出去，后发先至，在$N还没攻出时就破了$p的招数。]],["id"]=3,["textColor"]=[[YEL]]},["4"]={["action"]=[[但见$n举$w硬挡，乒的一声架开了来势汹汹的$N。]],["id"]=4,["textColor"]=[[YEL]]}},["sheyao"]={["1"]={["action"]=[[但是$n身子一侧，轻松地格开。]],["anim"]=[[snake-defend]],["hitPos"]=[[chest]],["id"]=1,["offset"]=-200,["textColor"]=[[YEL]]},["2"]={["action"]=[[但是$n身子一侧，轻松地格开。]],["anim"]=[[snake-defend]],["hitPos"]=[[foot]],["id"]=2,["offset"]=-200,["textColor"]=[[YEL]]},["3"]={["action"]=[[但是$n身子一侧，轻松地格开。]],["anim"]=[[snake-defend]],["hitPos"]=[[head]],["id"]=3,["offset"]=-200,["textColor"]=[[YEL]]}},["ti"]={["1"]={["action"]=[[$n护住要害，并一把将对方推开。]],["anim"]=[[bird-defend]],["hitPos"]=[[chest]],["id"]=1,["offset"]=-200,["textColor"]=[[默认]]},["2"]={["action"]=[[$n护住要害，并一把将对方推开。]],["anim"]=[[bird-defend]],["hitPos"]=[[foot]],["id"]=2,["offset"]=-200,["textColor"]=[[默认]]},["3"]={["action"]=[[$n护住要害，并一把将对方推开。]],["anim"]=[[bird-defend]],["hitPos"]=[[head]],["id"]=3,["offset"]=-200,["textColor"]=[[默认]]}},["vastBlade"]={["1"]={["action"]=[[见势不妙$n立刻将$W高举过头，“哐”一声双手传来震感，将$N的招式挡下。]],["id"]=1,["textColor"]=[[默认]]},["2"]={["action"]=[[$N来势汹汹$n不甘示弱将手中$W横在身前，“铮铮”两声将$N击来招数尽数化解。]],["id"]=2,["textColor"]=[[默认]]},["3"]={["action"]=[[$N见势击出一招，$n当即用手中$W抵挡，“铛铛”两声将其招数化解。]],["id"]=3,["textColor"]=[[默认]]}},["wugongyao"]={["1"]={["action"]=[[$n护住要害，并一把将对方推开。]],["anim"]=[[WuGong-defend]],["hitPos"]=[[chest]],["id"]=1,["offset"]=-200,["textColor"]=[[默认]]},["2"]={["action"]=[[$n护住要害，并一把将对方推开。]],["anim"]=[[WuGong-defend]],["hitPos"]=[[foot]],["id"]=2,["offset"]=-200,["textColor"]=[[默认]]},["3"]={["action"]=[[$n护住要害，并一把将对方推开。]],["anim"]=[[WuGong-defend]],["hitPos"]=[[head]],["id"]=3,["offset"]=-200,["textColor"]=[[默认]]}},["xiezici"]={["1"]={["action"]=[[$n护住要害，并一把将对方推开。]],["anim"]=[[XieZi-defend]],["hitPos"]=[[chest]],["id"]=1,["offset"]=-200,["textColor"]=[[默认]]},["2"]={["action"]=[[$n护住要害，并一把将对方推开。]],["anim"]=[[XieZi-defend]],["hitPos"]=[[foot]],["id"]=2,["offset"]=-200,["textColor"]=[[默认]]},["3"]={["action"]=[[$n护住要害，并一把将对方推开。]],["anim"]=[[XieZi-defend]],["hitPos"]=[[head]],["id"]=3,["offset"]=-200,["textColor"]=[[默认]]}},["xiyutiezhengyin"]={["1"]={["action"]=[[$n左手拇指食指虚捻，右手轻挥，空气中骤生RAN「变商」NOR之音，一轮音波将$N迫开。]],["id"]=1,["textColor"]=[[默认]]},["2"]={["action"]=[[$n两手凌空虚划，冷冽的气劲吹过，忽传RAN「清角」NOR之音，$N不觉有点心神撼动。]],["id"]=2,["textColor"]=[[默认]]},["3"]={["action"]=[[$n凝神专著，伸手轻抚，如拨琴弦，耳侧传来RAN「正宫」NOR之调，$N一时茫然不知所以。]],["id"]=3,["textColor"]=[[默认]]}},["yao"]={["1"]={["action"]=[[$n护住要害，并一把将对方推开。]],["anim"]=[[wolf-defend]],["hitPos"]=[[chest]],["id"]=1,["offset"]=-200,["textColor"]=[[默认]]},["2"]={["action"]=[[$n护住要害，并一把将对方推开。]],["anim"]=[[wolf-defend]],["hitPos"]=[[foot]],["id"]=2,["offset"]=-200,["textColor"]=[[默认]]},["3"]={["action"]=[[$n护住要害，并一把将对方推开。]],["anim"]=[[wolf-defend]],["hitPos"]=[[head]],["id"]=3,["offset"]=-200,["textColor"]=[[默认]]}},["yidaoliujianshu"]={["1"]={["action"]=[[$n一招「切返」以守为攻，化解了$N的攻势。]],["id"]=1,["textColor"]=[[YEL]]},["2"]={["action"]=[[$n突然从怀中掏出一把短刀，「二刀」“当”地一声挡住了$N的攻击。]],["id"]=2,["textColor"]=[[YEL]]}},["yitiantulonggong"]={["1"]={["action"]=[[$p但觉一股劲风袭至胸口，当下$W一带，画出一个上撇，刚好封住了$P$w的来势。]],["id"]=1,["textColor"]=[[YEL]]},["2"]={["action"]=[[危急之中，$p伸$W在$P的$w上一按，一借力，轻轻巧巧的避过，这一招乃是「武」字诀中的一戈。]],["id"]=2,["textColor"]=[[YEL]]},["3"]={["action"]=[[$p$W下掠，反手使出一记「刀」字诀，带住$P的$w，$W一撇一点，身子借势窜起。]],["id"]=3,["textColor"]=[[YEL]]},["4"]={["action"]=[[当下$p$W使一招「刀」字诀中的左撇，借着$P的来势，稍加拨动，当千钧一发之际，转危为安。]],["id"]=4,["textColor"]=[[YEL]]}},["zhizhuyao"]={["1"]={["action"]=[[但是$n身子一侧，轻松地格开。]],["anim"]=[[spider-defend]],["hitPos"]=[[chest]],["i